provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "public_data_010" {
  bucket = "pilot-public-data-010"
}

resource "aws_s3_bucket_policy" "public_data_010" {
  bucket = aws_s3_bucket.public_data_010.id

  policy = jsonencode({
    Version = "2012-10-17"

    Statement = [
      {
        Sid    = "PublicRead"
        Effect = "Allow"

        Principal = "*"

        Action = [
          "s3:GetObject"
        ]

        Resource = "${aws_s3_bucket.public_data_010.arn}/*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "privilege_escalation_010" {
  name = "pilot-privilege-escalation-010"
  user = aws_iam_user.escalation_target_010.name

  policy = jsonencode({
    Version = "2012-10-17"

    Statement = [
      {
        Effect   = "Allow"
        Action   = ["iam:AttachUserPolicy"]
        Resource = "*"
      }
    ]
  })
}

